<?php $detailUrl = url('?route=product_detail&id='.(int)$item['id']); ?>
<article class="product-card"><a class="product-image" href="<?= $detailUrl ?>"><img src="<?= $escape(get_product_image($item['image_url'] ?? '', $item['id'])) ?>" alt="<?= $escape($item['name']) ?>" loading="lazy" decoding="async" width="600" height="460"><?php if (!empty($item['is_best_seller']) || !empty($item['is_featured'])): ?><span class="product-label"><?= !empty($item['is_best_seller']) ? 'Best seller' : 'Featured' ?></span><?php endif; ?></a><div class="product-info"><p class="product-category"><?= $escape($item['category_name'] ?? 'Products') ?></p><h3><a href="<?= $detailUrl ?>"><?= $escape($item['name']) ?></a></h3><p class="product-description"><?= $escape(trim($item['description'] ?? '') ?: 'Take a closer look and make it part of your next order.') ?></p><div class="product-bottom"><strong><?= $escape($currency) ?><?= number_format((float)$item['price'], 2) ?></strong><form class="quick-add" action="<?= url('?route=cart/add') ?>" method="post"><input type="hidden" name="csrf_token" value="<?= $escape(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="qty" value="1"><button type="submit" aria-label="Add <?= $escape($item['name']) ?> to cart">Add to cart <span aria-hidden="true">+</span></button></form></div></div></article>
